create extension if not exists pgcrypto;
create extension if not exists citext;
create type user_status as enum ('INVITED','ACTIVE','SUSPENDED');
create type membership_role as enum ('OWNER','ADMIN','MANAGER','SHIFT_MANAGER','EMPLOYEE');
create type shift_status as enum ('DRAFT','PUBLISHED','CONFIRMED','DECLINED','COMPLETED','CANCELLED');
create type request_type as enum ('AVAILABILITY','TIME_OFF','SHIFT_SWAP');
create type request_status as enum ('PENDING','APPROVED','REJECTED','CANCELLED');
create type order_status as enum ('DRAFT','SUBMITTED','CONFIRMED','DELIVERED','CANCELLED');

create table organizations (id uuid primary key default gen_random_uuid(), name text not null, slug text not null unique, timezone text not null default 'Europe/Copenhagen', currency char(3) not null default 'DKK', created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table locations (id uuid primary key default gen_random_uuid(), organization_id uuid not null references organizations(id) on delete cascade, name text not null, slug text not null, address text, timezone text not null default 'Europe/Copenhagen', active boolean not null default true, created_at timestamptz not null default now(), unique(organization_id, slug));
create table users (id uuid primary key default gen_random_uuid(), email citext not null unique, name text not null, password_hash text not null, status user_status not null default 'ACTIVE', created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table memberships (id uuid primary key default gen_random_uuid(), organization_id uuid not null references organizations(id) on delete cascade, user_id uuid not null references users(id) on delete cascade, role membership_role not null, created_at timestamptz not null default now(), unique(organization_id,user_id));
create table sessions (id uuid primary key default gen_random_uuid(), user_id uuid not null references users(id) on delete cascade, organization_id uuid not null references organizations(id) on delete cascade, location_id uuid references locations(id) on delete set null, token_hash text not null unique, expires_at timestamptz not null, created_at timestamptz not null default now());
create index sessions_expiry_idx on sessions(expires_at);
create table employees (id uuid primary key default gen_random_uuid(), organization_id uuid not null references organizations(id) on delete cascade, user_id uuid references users(id) on delete set null, first_name text not null, last_name text not null, email citext, phone text, employment_title text, hourly_rate numeric(10,2), contracted_hours numeric(6,2), active boolean not null default true, created_at timestamptz not null default now(), unique(organization_id,email));
create table employee_locations (employee_id uuid not null references employees(id) on delete cascade, location_id uuid not null references locations(id) on delete cascade, primary_location boolean not null default false, primary key(employee_id,location_id));
create table shifts (id uuid primary key default gen_random_uuid(), organization_id uuid not null references organizations(id) on delete cascade, location_id uuid not null references locations(id) on delete cascade, employee_id uuid references employees(id) on delete set null, role text not null, starts_at timestamptz not null, ends_at timestamptz not null, break_minutes integer not null default 0, status shift_status not null default 'DRAFT', notes text, created_by uuid references users(id) on delete set null, published_at timestamptz, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), check(ends_at > starts_at));
create index shifts_location_date_idx on shifts(location_id,starts_at);
create table availability_rules (id uuid primary key default gen_random_uuid(), organization_id uuid not null references organizations(id) on delete cascade, employee_id uuid not null references employees(id) on delete cascade, weekday smallint check(weekday between 0 and 6), available_from time, available_to time, available boolean not null default true, valid_from date, valid_until date, note text, created_at timestamptz not null default now());
create table requests (id uuid primary key default gen_random_uuid(), organization_id uuid not null references organizations(id) on delete cascade, location_id uuid references locations(id) on delete set null, employee_id uuid not null references employees(id) on delete cascade, type request_type not null, status request_status not null default 'PENDING', starts_at timestamptz, ends_at timestamptz, payload jsonb not null default '{}'::jsonb, note text, reviewed_by uuid references users(id) on delete set null, reviewed_at timestamptz, created_at timestamptz not null default now());
create table suppliers (id uuid primary key default gen_random_uuid(), organization_id uuid not null references organizations(id) on delete cascade, name text not null, email citext, phone text, account_number text, delivery_notes text, active boolean not null default true, created_at timestamptz not null default now(), unique(organization_id,name));
create table products (id uuid primary key default gen_random_uuid(), organization_id uuid not null references organizations(id) on delete cascade, supplier_id uuid references suppliers(id) on delete set null, sku text, name text not null, category text not null, unit text not null, purchase_price numeric(12,2) not null default 0, active boolean not null default true, created_at timestamptz not null default now(), unique(organization_id,name));
create table location_inventory (location_id uuid not null references locations(id) on delete cascade, product_id uuid not null references products(id) on delete cascade, quantity numeric(12,3) not null default 0, par_level numeric(12,3) not null default 0, reorder_level numeric(12,3), updated_at timestamptz not null default now(), primary key(location_id,product_id));
create table purchase_orders (id uuid primary key default gen_random_uuid(), organization_id uuid not null references organizations(id) on delete cascade, location_id uuid not null references locations(id) on delete cascade, supplier_id uuid not null references suppliers(id), order_number text not null, status order_status not null default 'DRAFT', expected_delivery date, notes text, submitted_at timestamptz, created_by uuid references users(id) on delete set null, created_at timestamptz not null default now(), unique(organization_id,order_number));
create table purchase_order_items (id uuid primary key default gen_random_uuid(), purchase_order_id uuid not null references purchase_orders(id) on delete cascade, product_id uuid not null references products(id), quantity numeric(12,3) not null, unit_price numeric(12,2) not null, received_quantity numeric(12,3) not null default 0);
create table audit_logs (id bigserial primary key, organization_id uuid not null references organizations(id) on delete cascade, location_id uuid references locations(id) on delete set null, actor_user_id uuid references users(id) on delete set null, action text not null, entity_type text not null, entity_id text, before_data jsonb, after_data jsonb, metadata jsonb, created_at timestamptz not null default now());
create index audit_org_date_idx on audit_logs(organization_id,created_at desc);
create table notifications (id uuid primary key default gen_random_uuid(), organization_id uuid not null references organizations(id) on delete cascade, user_id uuid not null references users(id) on delete cascade, actor_user_id uuid references users(id) on delete set null, type text not null, title text not null, body text, href text, read_at timestamptz, created_at timestamptz not null default now());
create index notifications_user_idx on notifications(user_id,read_at,created_at desc);
